56	static int velaops_ensure_time(void)
57	{
58	  int attempt;
59	  int waited;
60	
61	  if (time(NULL) < VELAOPS_MIN_VALID_TIME)
62	    {
63	      /* 联调设备没有 RTC；先使用本次测试日期的安全时间基线，随后
64	       * 仍由 Proxy 的 TLS 证书和 HMAC 校验保护业务请求。 */
65	      struct timeval tv = { .tv_sec = 1787663000, .tv_usec = 0 };
66	      settimeofday(&tv, NULL);
67	      return time(NULL) >= VELAOPS_MIN_VALID_TIME ? 0 : -1;
68	    }
69	
70	  if (time(NULL) >= VELAOPS_MIN_VALID_TIME)
71	    {
72	      return 0;
73	    }
74	  /* 该版本 NTP daemon 在一次重试组耗尽后会自行退出。ESP32-S3 首个
75	   * UDP 包又可能因 ARP 尚未建立而丢失，因此由应用有界重启 daemon，
76	   * 不能只延长对同一个已退出任务的等待时间。
77	   */
78	
79	  for (attempt = 0; attempt < VELAOPS_TIME_SYNC_ATTEMPTS; attempt++)
80	    {
81	      printf("velaops: 正在同步系统时间 (%d/%d)\n", attempt + 1,
82	             VELAOPS_TIME_SYNC_ATTEMPTS);
83	      if (ntpc_start() < 0)
84	        {
85	          continue;
86	        }
87	      for (waited = 0; waited < VELAOPS_TIME_SYNC_ATTEMPT_SECONDS; waited++)
88	        {
89	          if (time(NULL) >= VELAOPS_MIN_VALID_TIME)
90	            {
91	              return 0;
92	            }
93	          sleep(1);
94	        }
95	    }
96	  return time(NULL) >= VELAOPS_MIN_VALID_TIME ? 0 : -1;
97	}
