99	static void velaops_hex_encode(const uint8_t *input, size_t input_len,
100	                               char *output)
101	{
102	  static const char digits[] = "0123456789abcdef";
103	  size_t index;
104	
105	  for (index = 0; index < input_len; index++)
106	    {
107	      output[index * 2] = digits[input[index] >> 4];
108	      output[index * 2 + 1] = digits[input[index] & 0x0f];
109	    }
110	  output[input_len * 2] = '\0';
111	}
