113	static int velaops_make_metadata(const char *device_id,
114	                                 velaops_auth_metadata_t *metadata,
115	                                 char request_id[33], char nonce[33])
116	{
117	  uint8_t random_bytes[32];
118	  time_t now;
119	
120	  if (velaops_ensure_time() != 0)
121	    {
122	      return -1;
123	    }
124	  now = time(NULL);
125	  /* 当前板级配置只启用了硬件 TRNG 对应的 /dev/random。显式请求该
126	   * 安全随机源，避免 getrandom() 默认访问未启用的 /dev/urandom。
127	   */
128	
129	  if (getrandom(random_bytes, sizeof(random_bytes), GRND_RANDOM) !=
130	      sizeof(random_bytes))
131	    {
132	      return -2;
133	    }
134	  velaops_hex_encode(random_bytes, 16, request_id);
135	  velaops_hex_encode(random_bytes + 16, 16, nonce);
136	  metadata->version = VELAOPS_PROTOCOL_VERSION;
137	  metadata->device_id = device_id;
138	  metadata->request_id = request_id;
139	  metadata->timestamp = (int64_t)now;
140	  metadata->nonce = nonce;
141	  return 0;
142	}
