144	static int velaops_get_memory_health(const char *result_json,
145	                                     const char **health)
146	{
147	  velaops_memory_observation_t observation;
148	  velaops_health_snapshot_t snapshot;
149	
150	  if (velaops_memory_result_parse(result_json, &observation) !=
151	      VELAOPS_MEMORY_RESULT_OK ||
152	      velaops_evaluate_memory(&observation,
153	                              VELAOPS_MEMORY_UNHEALTHY_PERCENT,
154	                              (int64_t)time(NULL), &snapshot) !=
155	      VELAOPS_HEALTH_OK)
156	    {
157	      fprintf(stderr, "velaops: Proxy 内存快照不可信\n");
158	      return -1;
159	    }
160	
161	  *health = snapshot.result == VELAOPS_HEALTH_HEALTHY ?
162	            "healthy" : "unhealthy";
163	  return 0;
164	}
