166	static int velaops_post_request(const char *target, const char *body,
167	                                const char *operation, bool evaluate_memory,
168	                                velaops_display_state_t *display_state)
169	{
170	  velaops_device_config_t config;
171	  velaops_proxy_tls_context_t tls_context;
172	  velaops_proxy_client_t client;
173	  velaops_auth_metadata_t metadata;
174	  velaops_proxy_response_t response;
175	  velaops_config_status_t config_status;
176	  velaops_proxy_client_status_t client_status;
177	  char request_id[33];
178	  char nonce[33];
179	  char *ca_pem = NULL;
180	  size_t ca_pem_len = 0;
181	  int metadata_status;
182	  int exit_status = EXIT_FAILURE;
183	  const char *health = NULL;
184	
185	  if (display_state != NULL)
186	    {
187	      display_state->online = 0;
188	    }
189	
190	  config_status = velaops_device_config_load(
191	      VELAOPS_CONFIG_FILE, VELAOPS_CA_FILE, &config, &ca_pem, &ca_pem_len);
192	  if (config_status != VELAOPS_CONFIG_OK)
193	    {
194	      fprintf(stderr, "velaops: 配置加载失败: %s\n",
195	              velaops_config_status_name(config_status));
196	      return EXIT_FAILURE;
197	    }
198	  metadata_status = velaops_make_metadata(config.device_id, &metadata,
199	                                           request_id, nonce);
200	  if (metadata_status != 0)
201	    {
202	      fprintf(stderr, "velaops: %s未就绪\n",
203	              metadata_status == -2 ? "安全随机源" : "系统时间");
204	      goto cleanup;
205	    }
206	
207	  tls_context.host = config.host;
208	  tls_context.port = config.port;
209	  tls_context.ca_pem = ca_pem;
210	  client.device_id = config.device_id;
211	  client.secret = (const uint8_t *)config.secret;
212	  client.secret_len = strlen(config.secret);
213	  client.transport = velaops_proxy_tls_transport;
214	  client.transport_context = &tls_context;
215	
216	  client_status = velaops_proxy_client_post_json(
217	      &client, target, (const uint8_t *)body, strlen(body),
218	      &metadata, &response);
219	  if (client_status != VELAOPS_PROXY_CLIENT_OK)
220	    {
221	      fprintf(stderr, "velaops: Proxy 请求失败: %s\n",
222	              velaops_proxy_client_status_name(client_status));
223	      goto cleanup;
224	    }
225	  if (!response.ok)
226	    {
227	      fprintf(stderr,
228	              "velaops: Proxy 拒绝: http=%d code=%s retryable=%s message=%s\n",
229	              response.http_status, response.error_code,
230	              response.retryable ? "true" : "false", response.error_message);
231	      goto cleanup;
232	    }
233	
234	  if (display_state != NULL)
235	    {
236	      display_state->online = 1;
237	    }
238	
239	  if (evaluate_memory &&
240	      velaops_get_memory_health(response.result_json, &health) != 0)
241	    {
242	      goto cleanup;
243	    }
244	  if (display_state != NULL && evaluate_memory)
245	    {
246	      velaops_health_snapshot_t snapshot;
247	      if (velaops_memory_result_parse(response.result_json,
248	                                      &display_state->memory) !=
249	          VELAOPS_MEMORY_RESULT_OK ||
250	          velaops_evaluate_memory(&display_state->memory,
251	                                  VELAOPS_MEMORY_UNHEALTHY_PERCENT,
252	                                  (int64_t)time(NULL), &snapshot) !=
253	          VELAOPS_HEALTH_OK)
254	        {
255	          display_state->online = 0;
256	          goto cleanup;
257	        }
258	      display_state->health = snapshot.result;
259	      display_state->observed_at = snapshot.observed_at;
260	    }
261	  if (display_state != NULL && !evaluate_memory)
262	    {
263	      if (velaops_resource_result_parse(response.result_json,
264	                                        &display_state->resources) != 0)
265	        {
266	          display_state->online = 0;
267	          goto cleanup;
268	        }
269	      display_state->has_resources = 1;
270	    }
271	  printf("velaops: %s成功 request_id=%s", operation, request_id);
272	  if (health != NULL)
273	    {
274	      printf(" health=%s", health);
275	    }
276	  printf(" result=%s\n", response.result_json);
277	  exit_status = EXIT_SUCCESS;
278	
279	cleanup:
280	  velaops_device_config_clear(&config);
281	  free(ca_pem);
282	  return exit_status;
283	}
