285	struct velaops_button_context_s
286	{
287	  int fd;
288	  btn_buttonset_t supported;
289	  btn_buttonset_t previous;
290	  unsigned int *page;
291	  velaops_display_t *display;
292	  velaops_display_state_t *state;
293	  pthread_mutex_t *display_lock;
294	};
295	
296	static void *velaops_button_worker(void *argument)
297	{
298	  struct velaops_button_context_s *context = argument;
299	  btn_buttonset_t sample;
300	
301	  for (;;)
302	    {
303	      if (read(context->fd, &sample, sizeof(sample)) == sizeof(sample))
304	        {
305	          if ((sample & context->supported) != 0 &&
306	              (context->previous & context->supported) == 0)
307	            {
308	              pthread_mutex_lock(context->display_lock);
309	              *context->page = (*context->page + 1) % 3;
310	              velaops_display_show(context->display, context->state,
311	                                   *context->page);
312	              pthread_mutex_unlock(context->display_lock);
313	            }
314	          context->previous = sample;
315	        }
316	      usleep(50000);
317	    }
318	  return NULL;
319	}
