321	int main(int argc, char *argv[])
322	{
323	  if (argc == 2 && strcmp(argv[1], "auth-check") == 0)
324	    {
325	      return velaops_post_request(VELAOPS_AUTH_TARGET, VELAOPS_AUTH_BODY,
326	                                  "认证", false, NULL);
327	    }
328	  if (argc == 2 && strcmp(argv[1], "check-memory") == 0)
329	    {
330	      /* CLI 只暴露预编译的结构化 Action，不接受用户传入任意
331	       * Action 名、目标或 JSON，从设备边界阻断命令注入。
332	       */
333	
334	      return velaops_post_request(VELAOPS_ACTION_TARGET,
335	                                  VELAOPS_CHECK_MEMORY_BODY, "内存巡检", true,
336	                                  NULL);
337	    }
338	
339	  if (argc == 2 && strcmp(argv[1], "monitor") == 0)
340	    {
341	      velaops_display_t *display;
342	      velaops_display_state_t state = {0};
343	      btn_buttonset_t supported;
344	      unsigned int page = 0;
345	      time_t next_refresh = 0;
346	      int button_fd;
347	      pthread_t button_thread;
348	      pthread_mutex_t display_lock = PTHREAD_MUTEX_INITIALIZER;
349	      struct velaops_button_context_s button_context;
350	
351	      display = velaops_display_open();
352	      if (display == NULL)
353	        {
354	          fprintf(stderr, "velaops: 无法打开 /dev/lcd0\n");
355	          return EXIT_FAILURE;
356	        }
357	      button_fd = open(VELAOPS_BUTTON_DEVICE, O_RDONLY | O_NONBLOCK);
358	      if (button_fd < 0 || ioctl(button_fd, BTNIOC_SUPPORTED,
359	                                 (unsigned long)(uintptr_t)&supported) < 0)
360	        {
361	          fprintf(stderr, "velaops: 无法打开 /dev/buttons\n");
362	          if (button_fd >= 0)
363	            {
364	              close(button_fd);
365	            }
366	          velaops_display_close(display);
367	          return EXIT_FAILURE;
368	        }
369	      button_context.fd = button_fd;
370	      button_context.supported = supported;
371	      button_context.previous = 0;
372	      button_context.page = &page;
373	      button_context.display = display;
374	      button_context.state = &state;
375	      button_context.display_lock = &display_lock;
376	      if (pthread_create(&button_thread, NULL, velaops_button_worker,
377	                         &button_context) != 0)
378	        {
379	          fprintf(stderr, "velaops: 无法启动按键线程\n");
380	          close(button_fd);
381	          velaops_display_close(display);
382	          return EXIT_FAILURE;
383	        }
384	      velaops_display_show(display, &state, page);
385	      for (;;)
386	        {
387	      if (time(NULL) >= next_refresh)
388	            {
389	              velaops_post_request(VELAOPS_ACTION_TARGET,
390	                                   VELAOPS_CHECK_RESOURCES_BODY, "资源巡检", false,
391	                                   &state);
392	              if (!state.online)
393	                {
394	                  velaops_recover_network();
395	                  velaops_post_request(VELAOPS_ACTION_TARGET,
396	                                       VELAOPS_CHECK_RESOURCES_BODY,
397	                                       "资源巡检重试", false, &state);
398	                }
399	              pthread_mutex_lock(&display_lock);
400	              velaops_display_show(display, &state, page);
401	              pthread_mutex_unlock(&display_lock);
402	              next_refresh = time(NULL) + VELAOPS_MONITOR_INTERVAL_SECONDS;
403	            }
404	          sleep(1);
405	        }
406	    }
407	
408	  fprintf(stderr, "用法: velaops <auth-check|check-memory|monitor>\n");
409	  return EXIT_FAILURE;
410	}
