15	static bool velaops_copy_text(char *destination, size_t capacity,
16	                              const char *source)
17	{
18	  size_t length;
19	
20	  if (destination == NULL || capacity == 0 || source == NULL)
21	    {
22	      return false;
23	    }
24	  length = strlen(source);
25	  if (length >= capacity)
26	    {
27	      return false;
28	    }
29	  memcpy(destination, source, length + 1);
30	  return true;
31	}
