33	static bool velaops_copy_json(char *destination, size_t capacity,
34	                              const cJSON *item)
35	{
36	  char *encoded;
37	  bool copied;
38	
39	  encoded = cJSON_PrintUnformatted(item);
40	  if (encoded == NULL)
41	    {
42	      return false;
43	    }
44	  copied = velaops_copy_text(destination, capacity, encoded);
45	  cJSON_free(encoded);
46	  return copied;
47	}
