49	static bool velaops_parse_request_id(const cJSON *root,
50	                                     const char *expected_request_id,
51	                                     velaops_proxy_response_t *response)
52	{
53	  const cJSON *request_id = cJSON_GetObjectItemCaseSensitive(root,
54	                                                             "request_id");
55	
56	  if (request_id == NULL)
57	    {
58	      return true;
59	    }
60	  if (!cJSON_IsString(request_id) || request_id->valuestring == NULL ||
61	      strlen(request_id->valuestring) != 32 ||
62	      strcmp(request_id->valuestring, expected_request_id) != 0)
63	    {
64	      return false;
65	    }
66	  response->has_request_id = true;
67	  return velaops_copy_text(response->request_id, sizeof(response->request_id),
68	                           request_id->valuestring);
69	}
