71	static bool velaops_parse_success(const cJSON *root,
72	                                  velaops_proxy_response_t *response)
73	{
74	  const cJSON *result = cJSON_GetObjectItemCaseSensitive(root, "result");
75	
76	  if (result == NULL)
77	    {
78	      return false;
79	    }
80	  response->ok = true;
81	  return velaops_copy_json(response->result_json,
82	                           sizeof(response->result_json), result);
83	}
