85	static bool velaops_parse_error(const cJSON *root,
86	                                velaops_proxy_response_t *response)
87	{
88	  const cJSON *error = cJSON_GetObjectItemCaseSensitive(root, "error");
89	  const cJSON *code;
90	  const cJSON *message;
91	  const cJSON *retryable;
92	
93	  if (!cJSON_IsObject(error))
94	    {
95	      return false;
96	    }
97	  code = cJSON_GetObjectItemCaseSensitive(error, "code");
98	  message = cJSON_GetObjectItemCaseSensitive(error, "message");
99	  retryable = cJSON_GetObjectItemCaseSensitive(error, "retryable");
100	  if (!cJSON_IsString(code) || code->valuestring == NULL ||
101	      !cJSON_IsString(message) || message->valuestring == NULL ||
102	      !cJSON_IsBool(retryable))
103	    {
104	      return false;
105	    }
