13	int velaops_proxy_tls_transport(
14	    void *context, const char *method, const char *target,
15	    const velaops_http_header_t *headers,
16	    const uint8_t *body, size_t body_len,
17	    char *response, size_t response_capacity, size_t *response_len)
18	{
19	  const velaops_proxy_tls_context_t *tls_context = context;
20	  vela_header_t tls_headers[VELAOPS_MAX_HTTP_HEADERS + 1];
21	  size_t header_count = 0;
22	  size_t received = 0;
23	  int status;
24	
25	  if (tls_context == NULL || tls_context->host == NULL ||
26	      tls_context->port == NULL || tls_context->ca_pem == NULL ||
27	      tls_context->ca_pem[0] == '\0' || method == NULL || target == NULL ||
28	      headers == NULL || response == NULL || response_capacity < 2 ||
29	      response_len == NULL || (body == NULL && body_len != 0))
30	    {
31	      return VELA_TLS_ERR_CONNECT;
32	    }
33	
34	  while (headers[header_count].name != NULL)
35	    {
36	      if (header_count >= VELAOPS_MAX_HTTP_HEADERS ||
37	          headers[header_count].value == NULL)
38	        {
39	          return VELA_TLS_ERR_OVERFLOW;
40	        }
41	      tls_headers[header_count].name = headers[header_count].name;
42	      tls_headers[header_count].value = headers[header_count].value;
43	      header_count++;
44	    }
45	  tls_headers[header_count].name = NULL;
46	  tls_headers[header_count].value = NULL;
47	
48	  status = vela_https_request_with_ca(
49	      tls_context->host, tls_context->port, method, target, tls_headers,
50	      (const char *)body, body_len, tls_context->ca_pem,
51	      response, response_capacity, &received);
52	  if (status < 0)
53	    {
54	      return status;
55	    }
56	
57	  /* vela_tls 会截断过大响应；宁可拒绝边界长度，也不解析半截 JSON。 */
58	  if (received >= response_capacity - 1)
59	    {
60	      return VELA_TLS_ERR_OVERFLOW;
61	    }
62	  *response_len = received;
63	  return status;
64	}
