/* 从 Proxy 的 /v1/time 端点获取真实 Unix 时间（无需 HMAC 认证）。
 * 用于 NTP 不可用时打破"需要时间才能认证、需要认证才能获取时间"的循环依赖。
 */
static int velaops_sync_time_from_proxy(void)
{
  velaops_device_config_t config;
  velaops_proxy_tls_context_t tls_context;
  char *ca_pem = NULL;
  size_t ca_pem_len = 0;
  char response[512];
  size_t received = 0;
  int http_status;
  velaops_http_header_t headers[2];
  cJSON *root = NULL;
  cJSON *result = NULL;
  cJSON *unix_time = NULL;
  struct timeval tv;
  int ret = -1;

  if (velaops_device_config_load(
          VELAOPS_CONFIG_FILE, VELAOPS_CA_FILE, &config,
          &ca_pem, &ca_pem_len) != VELAOPS_CONFIG_OK)
    {
      return -1;
    }

  tls_context.host = config.host;
  tls_context.port = config.port;
  tls_context.ca_pem = ca_pem;
  headers[0] = (velaops_http_header_t){NULL, NULL};

  /* 简单 GET 请求，不携带 HMAC 头 */
  http_status = velaops_proxy_tls_transport(
      &tls_context, "GET", VELAOPS_TIME_TARGET, headers,
      NULL, 0, response, sizeof(response), &received);

  if (http_status < 200 || http_status >= 300 || received == 0)
    {
      goto cleanup;
    }

  response[received] = '\0';
  root = cJSON_ParseWithLength(response, received);
  if (root == NULL)
    {
      goto cleanup;
    }

  result = cJSON_GetObjectItemCaseSensitive(root, "result");
  if (result == NULL)
    {
      goto cleanup;
    }

  unix_time = cJSON_GetObjectItemCaseSensitive(result, "unix_time");
  if (unix_time == NULL || !cJSON_IsNumber(unix_time))
    {
      goto cleanup;
    }

  tv.tv_sec = (time_t)unix_time->valuedouble;
  tv.tv_usec = 0;
  if (settimeofday(&tv, NULL) == 0 &&
      time(NULL) >= VELAOPS_MIN_VALID_TIME)
    {
      printf("velaops: 已从 Proxy 同步时间 %lld\n", (long long)tv.tv_sec);
      ret = 0;
    }

cleanup:
  cJSON_Delete(root);
  velaops_device_config_clear(&config);
  free(ca_pem);
  return ret;
}

